#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 int minMovesToMakePalindrome(string s){int ans=0;int l=0,r=(int)s.size()-1;
  while(l<r){int k=r;while(k>l&&s[k]!=s[l])--k;
   if(k==l){swap(s[l],s[l+1]);++ans;}
   else{for(int j=k;j<r;++j){swap(s[j],s[j+1]);++ans;}++l;--r;}
  }return ans;
 }
};
